var jsonData = pm.response.json();
if (jsonData.token) {
    var role = (jsonData.user && (jsonData.user.role || jsonData.user.baseRole)) || '';
    if (role.toUpperCase().indexOf('SUPER_ADMIN') !== -1) {
        pm.environment.set('SUPER_ADMIN_JWT_TOKEN', jsonData.token);
    } else if (role.toUpperCase().indexOf('FACULTY') !== -1) {
        pm.environment.set('FACULTY_JWT_TOKEN', jsonData.token);
    } else if (role.toUpperCase().indexOf('STUDENT') !== -1) {
        pm.environment.set('STUDENT_JWT_TOKEN', jsonData.token);
    } else if (role.toUpperCase().indexOf('HOD') !== -1) {
        pm.environment.set('HOD_JWT_TOKEN', jsonData.token);
    }
    pm.environment.set('JWT_TOKEN', jsonData.token);
}
pm.test('Status code is 200 or 201', function () {
    pm.expect(pm.response.code).to.be.oneOf([200, 201]);
});

